<?php
$args=[];$where='';if($user['role']==='employee'){$where=' WHERE l.employee_id=?';$args[]=$user['id'];}$rows=query_rows('SELECT l.*,u.full_name,u.employee_code,DATEDIFF(end_date,start_date)+1 AS days FROM leave_requests l JOIN users u ON u.id=l.employee_id'.$where.' ORDER BY l.id DESC',$args);
?><section class="card"><h2>Leave History</h2><div class="table-container"><table class="table"><thead><tr><th>Employee</th><th>Type / Dates</th><th>Days</th><th>Reason</th><th>Status / Response</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['employee_code'].' — '.$r['full_name'])?></td><td><?=h($r['leave_type'])?><br><?=h($r['start_date'].' to '.$r['end_date'])?></td><td><?=h($r['days'])?></td><td><?=h($r['reason'])?></td><td><?=h($r['status'])?><br><?=h($r['admin_note'])?></td><td><?php if($user['role']==='admin'):?><?php if($r['status']!=='Pending'):?>Done<?php else:?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><?php select_field('status','Decision',options(['Pending','Approved','Rejected']),$r['status']);input_field('admin_note','Response',$r['admin_note'],'text',false);?><button class="btn btn-primary" name="action" value="review">Save Decision</button></form><?php endif; ?><?php elseif($r['status']==='Pending'):?><div class="actions"><a class="btn btn-primary" href="?edit=<?=$r['id']?>">Edit</a><?php delete_form((int)$r['id']);?></div><?php else:?>Completed<?php endif;?></td></tr><?php endforeach;if(!$rows)echo '<tr><td colspan="6">No leave requests yet.</td></tr>';?></tbody></table></div></section>
